import type {
  ArcangelRequest,
  ArcangelResponse,
} from "@arcangel/framework/http"
import { confirmCartCreditLinesWorkflow } from "@arcangel/loyalty-plugin/workflows"

export async function POST(
  req: ArcangelRequest,
  res: ArcangelResponse
) {
  const { result } = await confirmCartCreditLinesWorkflow(req.scope)
    .run({
      input: {
        cart_id: "cart_123",
      },
    })

  res.send(result)
}

